#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstring>
#include <mutex>
#include <thread>

#include "backend.hpp"
#include "parallel.hpp"

// Generated by slangc -target cpp from shaders/atlas_far.slang (see CMakeLists.txt).
struct AtlasGroupRange {
    uint32_t start[3];
    uint32_t end[3];
};
extern "C" void farMain(void* varyingInput, void* entryPointParams, void* globalParams);
extern "C" void cloudMain(void* varyingInput, void* entryPointParams, void* globalParams);
extern "C" void sunMapMain(void* varyingInput, void* entryPointParams, void* globalParams);

namespace atlas {
namespace {

template <typename T>
CpuBuffer<T> view(const std::vector<T>& v) {
    return {const_cast<T*>(v.data()), v.size()};
}

using Clock = std::chrono::steady_clock;
double msSince(Clock::time_point t0) { return std::chrono::duration<double, std::milli>(Clock::now() - t0).count(); }

class CpuBackend final : public Backend {
public:
    const char* name() const override { return "cpu (slang->c++)"; }
    std::vector<float> dummyDepth_ = std::vector<float>(1, 1e30f);
    std::vector<uint32_t> dummyInfo_ = std::vector<uint32_t>(1, 0u);
    std::vector<uint32_t> dummyU32_ = std::vector<uint32_t>(1, 0u);
    std::vector<uint32_t> dummyU32x4_ = std::vector<uint32_t>(4, 0u);
    std::vector<uint64_t> dummyU64_ = std::vector<uint64_t>(1, 0u);
    std::vector<float> dummyLight_ = std::vector<float>(4, 0.0f);
    std::vector<float> cloud_, cloudDepth_, prevSurface_, outSurface_, prevCloud_, prevCloudDepth_;
    std::vector<float> sunMap_ = std::vector<float>(2, 0.0f);

    bool readSunMap(std::vector<float>& out, std::string&) override {
        std::lock_guard<std::mutex> lock(renderMu_);
        out = sunMap_.size() > 2 ? sunMap_ : std::vector<float>();
        return true;
    }

    bool render(const FrameInputs& in, FrameTargets& out, double* ms, std::string& err) override {
        if (injectedNow(err)) return false;  // atlas_debug_fault: the same failure paths without a GPU
        std::lock_guard<std::mutex> lock(renderMu_);
        return renderLocked(in, out, ms);
    }

    std::string info() const override {
        return std::string("{\"backend\":\"") + name() + "\",\"device\":\"CPU (" +
               std::to_string(std::max(1u, std::thread::hardware_concurrency())) + " threads)\"}";
    }

private:
    bool renderLocked(const FrameInputs& in, FrameTargets& out, double* ms) {
        auto t0 = Clock::now();
        uint32_t w = in.frame.dims[0], h = in.frame.dims[1];
        size_t n = size_t(w) * h;
        out.color.assign(n * 4, 0.0f);
        out.normal.assign(n, 0);
        out.depth.assign(n, 0.0f);
        out.counters.assign(n, 0);
        FrameGpu frame = in.frame;
        const PackedScene& s = *in.scene;
        FarGlobals g{};
        g.frame = &frame;
        g.regionTable = view(s.table);
        g.regions = view(s.regions);
        g.nodes = view(s.nodes);
        g.leaves = view(s.leaves);
        g.runEnd = view(s.runEnd);
        g.runMat = view(s.runMat);
        g.palette = view(*in.palette);
        g.outColor = {reinterpret_cast<Float4*>(out.color.data()), n};
        g.outNormal = view(out.normal);
        g.outDepth = view(out.depth);
        g.weather = view(*in.weather);
        g.counters = view(out.counters);
        g.cloudNoise = view(*in.cloudNoise);
        if (in.nearDepth) g.nearDepth = {const_cast<float*>(in.nearDepth), n};
        else g.nearDepth = view(dummyDepth_);
        // the near light (FRAME_NEAR_LIGHT, kept only with both near inputs): the kernel writes every pixel of it
        const bool primaryNear = (frame.dims[2] & FRAME_PRIMARY_NEAR_BITS) != 0;
        if ((frame.dims[2] & FRAME_NEAR_LIGHT_BIT) && ((in.nearInfo && in.nearDepth) || primaryNear)) {
            g.nearInfo = in.nearInfo ? CpuBuffer<uint32_t>{const_cast<uint32_t*>(in.nearInfo), n} : view(dummyInfo_);
            out.nearLight.assign(n * 4, 0.0f);
            g.outNearLight = {reinterpret_cast<Float4*>(out.nearLight.data()), n};
        } else {
            frame.dims[2] &= ~FRAME_NEAR_LIGHT_BIT;
            g.nearInfo = view(dummyInfo_);
            g.outNearLight = {reinterpret_cast<Float4*>(dummyLight_.data()), 1};
        }
        g.actors = view(in.actors);
        g.heightMip = view(s.heightMip);
        g.groupData = {reinterpret_cast<Uint4*>(const_cast<uint32_t*>(s.groups.data())), s.groups.size() / 4};
        // the level-0 grid: its pending sections built here, the reference of atlas_voxgrid.slang's kernels
        if (in.voxgrid && in.voxgrid->active()) {
            for (;;) {
                VgBatch b = in.voxgrid->take(1 << 30);
                if (!b.clear && b.jobs.empty() && !b.coarse()) break;
                in.voxgrid->applyCpu(b);
            }
        }
        g.texData = in.textures && !in.textures->empty() ? view(*in.textures) : view(dummyU32_);
        g.brickData = in.bricks && !in.bricks->empty() ? view(*in.bricks) : view(dummyU32_);
        g.farHit = {reinterpret_cast<Uint4*>(dummyU32x4_.data()), 1};
        g.prevFarHit = {reinterpret_cast<Uint4*>(dummyU32x4_.data()), 1};
        frame.dims[2] &= ~FRAME_FAR_AMORT_BIT;  // (internal to the Vulkan backend: a host's bit 30 never reaches this kernel)
        if (in.voxgrid && !in.voxgrid->chunks.empty()) {
            VoxGrid& vg = *in.voxgrid;
            g.vgChunks = view(vg.chunks);
            g.vgBlocks = vg.blocks.empty() ? view(dummyU32_) : view(vg.blocks);
            g.vgBits = vg.bits.empty() ? view(dummyU64_) : view(vg.bits);
            g.vgPool = vg.pool.empty() ? view(dummyU32_) : view(vg.pool);
            frame.vgOrigin[0] = vg.cpuOx;  // (the window these arrays hold: the books may have moved on since)
            frame.vgOrigin[2] = vg.cpuOz;
            for (int k = 1; k < VG_LEVELS; k++) {
                frame.vgLevel[k - 1][0] = vg.cpuLevelO[k][0];
                frame.vgLevel[k - 1][1] = vg.cpuLevelO[k][1];
            }
        } else {
            frame.vgOrigin[3] = 0;  // (no grid here yet)
            for (int k = 1; k < VG_LEVELS; k++) frame.vgLevel[k - 1][3] = 0;
            g.vgChunks = g.vgBlocks = g.vgPool = view(dummyU32_);
            g.vgBits = view(dummyU64_);
        }
        // the half-resolution cloud pass reads the last frame's surfaces (none yet, or after a resize: no limit)
        uint32_t dv = (frame.dims[2] & 0x80u) ? 4u : 2u;  // FRAME_CLOUDS_QUARTER
        size_t cn = size_t((w + dv - 1) / dv) * ((h + dv - 1) / dv);
        if (prevCloud_.size() != cn * 4) {
            prevCloud_.assign(cn * 4, 0.0f);
            prevCloudDepth_.assign(cn, 1e30f);
        }
        cloud_.assign(cn * 4, 0.0f);
        cloudDepth_.assign(cn, 1e30f);
        g.prevCloudBuf = {reinterpret_cast<Float4*>(prevCloud_.data()), cn};
        g.prevCloudDepth = view(prevCloudDepth_);
        if (prevSurface_.size() != n) prevSurface_.assign(n, 1e30f);
        outSurface_.assign(n, 1e30f);
        g.cloudBuf = {reinterpret_cast<Float4*>(cloud_.data()), cn};
        g.cloudDepth = view(cloudDepth_);
        g.prevSurface = view(prevSurface_);
        g.outSurface = view(outSurface_);
        uint32_t sms = frame.sunMapRows[3] ? frame.sunMapRows[2] : 0;
        if (sms && sunMap_.size() != size_t(sms) * (sms + 1) * 2) sunMap_.assign(size_t(sms) * (sms + 1) * 2, 0.0f);
        g.sunMap = {reinterpret_cast<Float2*>(sunMap_.data()), sunMap_.size() / 2};

        auto dispatch = [&](void (*kernel)(void*, void*, void*), uint32_t gx, uint32_t gy) {
            std::atomic<uint32_t> nextRow{0};
            auto worker = [&] {
                for (;;) {
                    uint32_t row = nextRow.fetch_add(1);
                    if (row >= gy) return;
                    AtlasGroupRange r{{0, row, 0}, {gx, row + 1, 1}};
                    kernel(&r, nullptr, &g);
                }
            };
            parallelRun(worker, 0);
        };
        if (frame.dims[2] & 0x1u)  // FRAME_CLOUDS
            dispatch(cloudMain, ((w + dv - 1) / dv + 7) / 8, ((h + dv - 1) / dv + 7) / 8);
        dispatch(farMain, (w + 7) / 8, (h + 7) / 8);
        if (sms) dispatch(sunMapMain, (sms + 7) / 8, (frame.sunMapRows[1] + 1 + 7) / 8);
        prevSurface_.swap(outSurface_);
        if (frame.dims[2] & 0x1u) {
            prevCloud_.swap(cloud_);
            prevCloudDepth_.swap(cloudDepth_);
        }
        if (ms) *ms = msSince(t0);
        return true;
    }

    std::mutex renderMu_;  // the kernel's own state (cloud and surface history, the sun map)
};

}  // namespace

std::unique_ptr<Backend> makeCpuBackend() { return std::make_unique<CpuBackend>(); }

}  // namespace atlas
